contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address keeper, address owner, uint256 threshold) public {
        vm.assume(owner != address(0));
        vm.assume(keeper != address(0));
        vm.assume(owner != keeper);

        // Initialize the contract with valid non-zero addresses to pass initialization.
        // The initialize function requires specific dependencies, but we can deploy
        // minimal mocks that satisfy the interfaces only for the purpose of testing paused().
        // Actually, C's initialize expects specific interfaces and performs operations.
        // To isolate paused(), we can directly manipulate the pause state via the owner.
        // However, C uses OwnableUpgradeable and PausableUpgradeable, so we need to
        // properly initialize it first with proxy-like setup, but since deploy is a fresh
        // contract we call initialize with mock addresses that exist and have code?
        // We don't want to hardcode the scenario, but we must make the contract functional
        // enough to call pause/unpause and observe paused().
        // The simplest way: deploy minimal mock contracts that satisfy the interfaces
        // so that initialize succeeds. We'll fuzz the inputs, but the mock addresses
        // need to be contracts with code. So we deploy them here.
        MockERC20 sGlp = new MockERC20();
        MockERC20 usdc = new MockERC20();
        MockRewardRouter router = new MockRewardRouter();
        MockGlpManager glpManager = new MockGlpManager();
        address vault = address(new MockJuniorVault());
        c.initialize(sGlp, usdc, IRewardRouterV2(address(router)), IGlpManager(address(glpManager)), vault, keeper);

        // Transfer ownership to the fuzzed owner address
        vm.prank(owner);
        c.transferOwnership(owner);

        // Set threshold
        vm.prank(owner);
        c.setThresholds(threshold);

        // At this point, contract is unpaused (default after initialization).
        bool pausedBefore = c.paused();
        bool expectedUnpausedInitially = !pausedBefore; // reference: pausedBefore should be false.
        // But we just assert that the contract is not paused initially.
        assertTrue(!pausedBefore);

        // Owner pauses the contract
        vm.prank(owner);
        c.pauseDeposit();

        bool pausedAfter = c.paused();
        // Reference should return true; mutant returns false.
        assertTrue(pausedAfter);
    }
